import re

class CommonMethods:

    # Case-sensitive natural sorting
    @staticmethod
    def natural_keys(text):
        """
        Sorts list of dataclass to specified order.
        Works with list of dataclasses if used like this:
        _list = sorted(LIST_OF_SAME_DATACLASS, key=lambda d: GuiCommonMethods.natural_keys(d.connectedPortName))

        For list of normal strings, use the following:
        alist.sort(key=natural_keys)      # sorts in human order [ANT2, ANT12, ANT26 etc...]

        Source:
        http://nedbatchelder.com/blog/200712/human_sorting.html
        https://stackoverflow.com/questions/5967500/how-to-correctly-sort-a-string-with-a-number-inside
        """

        def _atoi(text):
            return int(text) if text.isdigit() else text

        return [_atoi(c) for c in re.split(r'(\d+)', str(text))]

    # Case-insensitive natural sorting
    @staticmethod
    def natural_sort_key(s, _nsre=re.compile('([0-9]+)')):
        """
        Sort the list by the 'name' attribute in a human-readable way
        sorted_by_name = sorted(LIST_OF_SAME_DATACLASS, key=lambda x: natural_sort_key(x.name))
        """
        return [int(text) if text.isdigit() else text.lower() for text in _nsre.split(s)]